/* Arcana Forge — browser UI and collaborative editor */
(() => {
'use strict';
const D = window.ArcanaDefaults;
const socket = io({reconnection:true});
const $ = (s,r=document)=>r.querySelector(s);
const clone=x=>JSON.parse(JSON.stringify(x));
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const color=(s,def='#b9a17d')=>/^#[0-9a-fA-F]{3,8}$/.test(s||'')?s:def;
const img=s=>typeof s==='string'&&(/^(https?:\/\/)/i.test(s)||/^data:image\/(jpeg|png|webp|gif);base64,/i.test(s))?h(s):'';
const worldKey='arcana-forge-worlds-v1';
const loadWorlds=()=>{try{const worlds=JSON.parse(localStorage.getItem(worldKey)||'null');return Array.isArray(worlds)?worlds:D.makeSamples();}catch{return D.makeSamples();}};
let worlds=loadWorlds();
const state={view:'home',room:null,draft:null,fromRoom:false,selection:worlds[0]?.id||null,tab:'board',chosenCell:null,chosenLayer:null,chosenCharacter:null,deck:'adventure',chosenCard:null,modal:null,editorTool:'select',linkSource:null,zoom:1,pendingWorldId:null,joiningCode:new URLSearchParams(location.search).get('room')||'',name:localStorage.getItem('arcana-nickname')||'',connected:false,toastTimer:null};
const effects=[['draw_adventure','Draw adventure'],['draw_item','Draw item'],['draw_spell','Draw spell'],['gold','Change gold'],['health','Change life'],['strength','Change strength'],['craft','Change craft'],['fate','Change fate'],['teleport','Teleport'],['shop','Merchant shop'],['choice','Choice: gold or life'],['victory','Win the game'],['message','Narrative message']];
const spellTypes=[['heal','Restore life'],['gold','Grant gold'],['power','Combat boost'],['reroll','Reroll movement'],['draw_spell','Draw spell'],['teleport','Teleport to start'],['flee','Escape encounter']];
const deckNames={adventure:'Adventure',item:'Items',spell:'Spells'};
const sel=(options,value)=>options.map(([v,label])=>`<option value="${h(v)}" ${String(value)===String(v)?'selected':''}>${h(label)}</option>`).join('');
const field=(label,bind,value,type='text',extra='')=>`<label class="field"><span>${h(label)}</span><input type="${type}" data-bind="${h(bind)}" value="${h(value)}" ${extra}/></label>`;
const area=(label,bind,value)=>`<label class="field"><span>${h(label)}</span><textarea rows="3" data-bind="${h(bind)}">${h(value)}</textarea></label>`;
const dropdown=(label,bind,options,value)=>`<label class="field"><span>${h(label)}</span><select data-bind="${h(bind)}">${sel(options,value)}</select></label>`;
function toast(message,isError=false){const el=$('#toast');el.innerHTML=`<div class="toast-message ${isError?'error':''}">${h(message)}</div>`;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>{el.innerHTML=''},3900);}
function persist(){try{localStorage.setItem(worldKey,JSON.stringify(worlds));return true;}catch{toast('Storage is full. Export your world as JSON, or use smaller artwork.',true);return false;}}
function currentWorld(){return worlds.find(w=>w.id===state.selection)||worlds[0]||D.makeDefault();}
function me(){return state.room?.players.find(p=>p.id===state.room.youId);}
function isHost(){return !!state.room&&state.room.youId===state.room.hostId;}
function isMyTurn(){return state.room?.status==='playing'&&state.room.game&&state.room.players[state.room.game.turnIndex]?.id===state.room.youId;}
function hero(w,p){return w.characters.find(c=>c.id===p.characterId);}
function sourceForCell(w,id){return w.cells.find(x=>x.id===id);}
function scenePositions(w){const map={};for(const layer of w.layers){const cs=w.cells.filter(c=>c.layerId===layer.id);cs.forEach((cell,i)=>{const angle=-Math.PI/2+(2*Math.PI*i/Math.max(1,cs.length));const r=Math.max(6,Math.min(47,Number(layer.radius)||30));map[cell.id]={x:Number.isFinite(Number(cell.x))&&cell.x!==null?Number(cell.x):50+r*Math.cos(angle),y:Number.isFinite(Number(cell.y))&&cell.y!==null?Number(cell.y):50+r*Math.sin(angle)};});}return map;}
function board(w,mode='preview',room=null){
  const positions=scenePositions(w),layers=w.layers||[];
  const svgRings=layers.map(l=>`<circle class="board-ring" cx="500" cy="500" r="${(Math.max(6,Math.min(47,Number(l.radius)||30))*10)}" style="stroke:${color(l.color)}50"></circle>`).join('');
  const already=new Set();const svgLinks=[];
  for(const c of w.cells){for(const linked of c.links||[]){if(!positions[linked]||!positions[c.id])continue;const key=[c.id,linked].sort().join('|');if(already.has(key))continue;already.add(key);let a=positions[c.id],b=positions[linked];svgLinks.push(`<path class="board-link" d="M ${a.x*10} ${a.y*10} L ${b.x*10} ${b.y*10}"/>`);}}
  const myTurn=room&&room.status==='playing'&&room.players[room.game?.turnIndex]?.id===room.youId;
  const reachable=(myTurn&&room.game?.phase==='move')?(room.game.moves||[]):[];
  const tiles=w.cells.map(c=>{
    const pos=positions[c.id];if(!pos)return '';
    const layer=layers.find(l=>l.id===c.layerId),tc=color(c.color||layer?.color);
    const people=room?.players.filter(p=>p.position===c.id)||[];
    const cls=['tile'];if(c.image)cls.push('has-image');if(mode==='editor')cls.push('editable');if(mode==='editor'&&state.chosenCell===c.id)cls.push('selected');if(reachable.includes(c.id))cls.push('reachable');
    return `<button type="button" class="${cls.join(' ')}" data-action="tile" data-id="${h(c.id)}" style="left:${pos.x}%;top:${pos.y}%;--tile-color:${tc};${c.image?'--tile-image:url(\''+img(c.image)+'\');':''}" title="${h(c.name)} — ${h(c.description||'')}" aria-label="${h(c.name)}">
      <span class="tile-icon">${h(c.icon||'✦')}</span><span class="tile-name">${h(c.name)}</span>${people.length?`<span class="tokens">${people.slice(0,4).map(p=>`<span class="token" title="${h(p.name)}" style="background:${color(hero(w,p)?.color,'#506b87')}">${h(hero(w,p)?.icon||p.name[0])}</span>`).join('')}</span>`:''}
    </button>`;
  }).join('');
  const bg=img(w.theme?.boardImage||'');
  return `<div class="board-scroll"><div class="board-scene" style="--world-bg:${color(w.theme?.background,'#101722')};--world-accent:${color(w.theme?.accent,'#edc98d')};${mode!=='preview'?`min-width:${Math.round(650*state.zoom)}px;max-width:${Math.round(1000*state.zoom)}px;`:''}">
  ${bg?`<img class="board-backdrop" alt="World backdrop" style="opacity:${Math.max(0,Math.min(1,Number(w.theme?.boardOpacity??.5)))}" src="${bg}" />`:''}
  <svg class="board-svg" viewBox="0 0 1000 1000" aria-hidden="true"><circle cx="500" cy="500" r="480" fill="none" stroke="#d6b27722" stroke-width="8"/><path d="M500 12V988M12 500H988" stroke="#cda96a18" stroke-width="1"/>${svgRings}${svgLinks.join('')}</svg>
  <div class="board-center"><div class="sigil">✦</div><div class="sigil-label">ARCANA</div></div>${tiles}</div></div>`;
}
function boardFooter(w){return `<div class="board-foot"><div class="dots">${w.layers.map(l=>`<span><i class="ring-dot" style="background:${color(l.color)}"></i>${h(l.name)}</span>`).join('')}</div><span>${w.cells.length} spaces</span></div>`;}
function topbar(){return `<header class="site-header"><div class="brand" data-action="home"><span class="brand-symbol">✦</span><div><div class="brand-name">ARCANA FORGE</div><div class="brand-sub">Worlds worth getting lost in</div></div></div><nav class="top-nav"><button data-action="home" class="${state.view==='home'?'active':''}">World Library</button><button data-action="new-world" class="${state.view==='editor'?'active':''}">World Builder</button><button data-action="help" class="${state.view==='help'?'active':''}">How to Play</button>${state.room?`<button data-action="view-room" class="${['game','lobby'].includes(state.view)?'active':''}">Live Adventure</button><span class="room-pill">${h(state.room.code)}</span>`:''}</nav></header>`;}
function home(){let featured=currentWorld();return `<main class="page"><section class="hero"><div class="hero-copy"><div class="eyebrow">THE ADVENTURE IS YOURS TO CREATE</div><h1>Forge a world.<br/><em>Write its fate.</em></h1><p class="hero-lead">Create your own tabletop fantasy adventure, shape every space and card, and explore it in real time with friends. One canvas. Infinite stories.</p><div class="hero-buttons"><button class="btn gold-btn" data-action="new-world">✦ Create a World</button><button class="btn ghost" data-action="open-join">◇ Join a Friend</button></div><div class="features-line"><span>Build any board</span><span>Fully custom decks</span><span>Live multiplayer</span><span>Made for every screen</span></div></div><div class="hero-art">${board(featured,'preview')}<div class="hero-badge">✧ YOUR WORLD · YOUR RULES</div></div></section>
  <section id="world-library"><div class="section-head"><div><div class="eyebrow">THE LIBRARY</div><h2>Your Worlds</h2></div><span class="muted small">Worlds are saved in this browser. Export to share or back them up.</span></div>
  <div class="library-grid">${worlds.map(w=>`<div class="world-card"><div class="world-banner" ${w.theme?.boardImage?`style="background-image:linear-gradient(#1018289c,#0f1623bc),url('${img(w.theme.boardImage)}');background-size:cover;background-position:center"`:''}><span class="world-icon">✦</span></div><div class="world-body"><h3>${h(w.title)}</h3><p>${h(w.tagline||w.description||'Your next adventure begins here.')}</p><div class="world-meta"><span>◎ ${w.layers.length} layers</span><span>◇ ${w.cells.length} spaces</span><span>✧ ${w.characters.length} heroes</span></div><div class="world-actions"><button class="btn gold-btn sm" data-action="host-world" data-id="${h(w.id)}">Host Game</button><button class="btn sm" data-action="edit-world" data-id="${h(w.id)}">Customize</button><button class="btn sm icon-btn" data-action="export-world" data-id="${h(w.id)}" title="Export world as JSON">⇩</button><button class="btn sm icon-btn" data-action="duplicate-world" data-id="${h(w.id)}" title="Duplicate world">⧉</button>${worlds.length>1?`<button class="btn sm icon-btn danger" data-action="delete-world" data-id="${h(w.id)}" title="Delete world">×</button>`:''}</div></div></div>`).join('')}
  <button class="empty-card" data-action="new-world"><span class="big-plus">＋</span><strong>Start from a blank world</strong><span class="small">Your lands, heroes, encounters and story.</span></button></div></section>
  <section class="join-strip"><div><h3>An invitation to adventure?</h3><p>Enter a room code from your friend and join their world instantly.</p></div><div class="join-entry"><input id="home-code" class="code-input" maxlength="6" placeholder="ROOM CODE" value="${h(state.joiningCode)}" aria-label="Room code"/><button class="btn gold-btn" data-action="join-code">Join Room →</button></div></section>${footer()}</main>`;}
function footer(){return `<footer class="site-footer">✦ ARCANA FORGE &nbsp;·&nbsp; CREATE ORIGINAL WORLDS &nbsp;·&nbsp; PLAY TOGETHER, ANYWHERE</footer>`;}
function zoomTools(){return `<div><button class="btn sm icon-btn" data-action="zoom-out" title="Zoom out">−</button> <button class="btn sm icon-btn" data-action="zoom-in" title="Zoom in">＋</button> <button class="btn sm" data-action="zoom-reset">Fit</button></div>`;}
function editor(){const w=state.draft;if(!w)return home();return `<main class="page"><div class="page-top"><div><div class="eyebrow">WORLD BUILDER ${state.fromRoom?'· EDITING LIVE LOBBY':''}</div><h2>${h(w.title)}</h2><div class="small muted">Tap a space to edit it. Drag spaces to rearrange them. Link spaces to build branching routes.</div></div><div class="page-actions"><button class="btn sm" data-action="export-draft">⇩ Export</button><button class="btn sm" data-action="import-open">⇧ Import</button>${state.fromRoom?`<button class="btn sm positive" data-action="apply-room-world">✓ Apply to Lobby</button>`:`<button class="btn sm" data-action="save-world">✓ Save</button><button class="btn sm gold-btn" data-action="host-draft">▶ Host this World</button>`}<button class="btn sm ghost" data-action="close-editor">Close</button></div></div>
  <div class="editor-layout"><section class="panel board-panel"><div class="board-toolbar"><div><div class="eyebrow no-line">WORLD CANVAS</div><div class="board-toolbar-note tiny muted">${state.editorTool==='link'?'Select two spaces to connect them':'Click to inspect · Drag to place · Scroll to pan on mobile'}</div></div>${zoomTools()}</div>${board(w,'editor')}${boardFooter(w)}</section><aside class="panel inspector"><div class="tabs">${[['board','World'],['layer','Layers'],['cell','Spaces'],['character','Heroes'],['cards','Cards'],['rules','Rules']].map(([k,v])=>`<button class="${state.tab===k?'active':''}" data-action="editor-tab" data-id="${k}">${v}</button>`).join('')}</div><div class="inspector-body">${inspector()}</div></aside></div>${footer()}</main>`;}
function inspector(){const w=state.draft;switch(state.tab){case 'board':return inspectBoard(w);case 'layer':return inspectLayer(w);case 'cell':return inspectCell(w);case 'character':return inspectCharacter(w);case 'cards':return inspectCards(w);case 'rules':return inspectRules(w);default:return ''}}
const upload=(label,target)=>`<label class="upload-box">⇧ ${h(label)}<input type="file" accept="image/*" data-upload="${h(target)}" /></label>`;
function inspectBoard(w){const theme=w.theme||{};return `<h3>World Identity</h3>${field('World title','board.title',w.title)}${field('Tagline','board.tagline',w.tagline||'')}${area('World description','board.description',w.description)}<div class="divider"></div><h3>Art & Atmosphere</h3><div class="two-fields">${field('Accent color','board.theme.accent',theme.accent||'#d8af70','color')}${field('Board background','board.theme.background',theme.background||'#101722','color')}</div>${theme.boardImage?`<img class="thumbnail" src="${img(theme.boardImage)}" alt="Board artwork"/>`:''}${upload('Upload board background','board')}${field('Artwork opacity (0 to 1)','board.theme.boardOpacity',theme.boardOpacity??0.5,'number','min="0" max="1" step="0.05"')}<div class="row-actions"><button class="btn sm ghost" data-action="clear-image" data-target="board">Remove background</button></div><div class="divider"></div><div class="code-hint">✦ Everything you design is part of the world: layers, freely positioned spaces, connected routes, characters, images, and all three card decks. Save or export to share it.</div>`;}
function inspectLayer(w){const layer=w.layers.find(l=>l.id===state.chosenLayer)||w.layers[0];if(!layer)return '<p>No layers yet.</p>';const count=w.cells.filter(c=>c.layerId===layer.id).length;return `<div class="row-actions"><h3>Board Layers</h3><button class="btn sm positive" data-action="add-layer">＋ New</button></div><div class="inspector-list">${w.layers.map(l=>`<button class="list-row ${l.id===layer.id?'active':''}" data-action="select-layer" data-id="${h(l.id)}"><span class="row-icon" style="color:${color(l.color)}">◉</span><span class="grow">${h(l.name)}<small>${w.cells.filter(c=>c.layerId===l.id).length} spaces</small></span><span class="row-end">${h(l.radius)}%</span></button>`).join('')}</div><div class="divider"></div><h3>Edit Layer</h3>${field('Layer name','layer.name',layer.name)}${field('Radius (%)','layer.radius',layer.radius,'number','min="7" max="47"')}${field('Layer color','layer.color',color(layer.color),'color')}<div class="row-actions"><span class="small muted">${count} spaces on this layer</span><button class="btn sm" data-action="add-cell" data-layer="${h(layer.id)}">＋ Space</button></div><div class="row-actions"><button class="btn sm ghost" data-action="reset-layer-layout">Reset space positions</button><button class="btn sm danger" data-action="delete-layer">Delete layer</button></div><div class="quick-tip">Each layer forms a loop. Add links between spaces on different layers, or create shortcuts within one layer.</div>`;}
function effectEditor(actions,prefix){return `<div class="effects">${actions.map((fx,i)=>`<div class="effect-card"><div class="effect-title"><strong>ACTION ${i+1}</strong><button class="btn sm danger" data-action="remove-effect" data-prefix="${prefix}" data-index="${i}">×</button></div>${dropdown('Effect',`${prefix}.${prefix==='card'?'effects':'actions'}.${i}.type`,effects,fx.type)}${!['draw_adventure','victory','message'].includes(fx.type)?field('Amount (negative to subtract)',`${prefix}.${prefix==='card'?'effects':'actions'}.${i}.amount`,fx.amount??1,'number'):''}${fx.type==='teleport'?dropdown('Destination',`${prefix}.${prefix==='card'?'effects':'actions'}.${i}.targetId`,state.draft.cells.map(c=>[c.id,c.name]),fx.targetId):''}${area('Optional narrative text',`${prefix}.${prefix==='card'?'effects':'actions'}.${i}.text`,fx.text||'')}</div>`).join('')}</div><button class="btn sm block" data-action="add-effect" data-prefix="${prefix}">＋ Add action</button>`;}
function inspectCell(w){const c=sourceForCell(w,state.chosenCell)||w.cells[0];if(!c)return '<p>Create a space first.</p>';const layer=w.layers.find(l=>l.id===c.layerId);return `<div class="row-actions"><h3>Space Editor</h3><button class="btn sm positive" data-action="add-cell" data-layer="${h(c.layerId)}">＋ New</button></div><label class="field"><span>Choose a space</span><select data-action-select="select-cell">${sel(w.cells.map(x=>[x.id,`${x.name} (${w.layers.find(l=>l.id===x.layerId)?.name||''})`]),c.id)}</select></label><div class="divider"></div>${field('Space name','cell.name',c.name)}${field('Small subtitle','cell.subtitle',c.subtitle||'')}${area('Landing narration','cell.description',c.description||'')}<div class="two-fields">${field('Symbol (emoji or glyph)','cell.icon',c.icon||'✦')}${field('Space color','cell.color',color(c.color||layer?.color),'color')}</div>${dropdown('Layer','cell.layerId',w.layers.map(l=>[l.id,l.name]),c.layerId)}${c.image?`<img class="thumbnail" src="${img(c.image)}" alt="Space art" />`:''}${upload('Upload space artwork','cell')}<button class="btn sm ghost" data-action="clear-image" data-target="cell">Remove image</button><div class="divider"></div><div class="row-actions"><h3>When Landed On</h3><span class="tiny muted">Sequence of effects</span></div>${effectEditor(c.actions||[],'cell')}<div class="divider"></div><div class="row-actions"><h3>Routes & Links</h3><button class="btn sm ${state.editorTool==='link'?'positive':''}" data-action="link-mode">${state.editorTool==='link'?'Cancel linking':'＋ Link spaces'}</button></div>${state.editorTool==='link'?`<div class="link-source">${state.linkSource?'Now select the destination space on the board.':'Select your first space, then another space to connect them.'}</div>`:''}${(c.links||[]).map(link=>`<div class="list-row"><span class="grow">⇄ ${h(sourceForCell(w,link)?.name||'Missing space')}</span><button class="btn sm danger" data-action="unlink" data-id="${h(link)}">×</button></div>`).join('')}<div class="divider"></div><div class="row-actions"><button class="btn sm" data-action="reset-cell-position">Reset position</button><button class="btn sm danger" data-action="delete-cell">Delete space</button></div>`;}
function inspectCharacter(w){const c=w.characters.find(x=>x.id===state.chosenCharacter)||w.characters[0];if(!c)return `<button class="btn gold-btn" data-action="add-character">Add first hero</button>`;return `<div class="row-actions"><h3>Characters</h3><button class="btn sm positive" data-action="add-character">＋ Hero</button></div><div class="inspector-list">${w.characters.map(x=>`<button class="list-row ${c.id===x.id?'active':''}" data-action="select-character" data-id="${h(x.id)}"><span class="row-icon" style="color:${color(x.color)}">${h(x.icon||'✦')}</span><span class="grow">${h(x.name)}<small>${h(x.title||'Adventurer')}</small></span></button>`).join('')}</div><div class="divider"></div>${field('Name','character.name',c.name)}${field('Title','character.title',c.title||'')}<div class="two-fields">${field('Symbol','character.icon',c.icon||'✦')}${field('Color','character.color',color(c.color),'color')}</div>${c.image?`<img class="thumbnail" src="${img(c.image)}" alt="Character art"/>`:''}${upload('Upload hero portrait','character')}<button class="btn sm ghost" data-action="clear-image" data-target="character">Remove portrait</button><div class="divider"></div><h3>Starting Statistics</h3><div class="two-fields">${field('Life','character.health',c.health,'number','min="1" max="20"')}${field('Strength','character.strength',c.strength,'number','min="0" max="30"')}${field('Craft / Magic','character.craft',c.craft,'number','min="0" max="30"')}${field('Fate','character.fate',c.fate,'number','min="0" max="30"')}${field('Gold','character.gold',c.gold,'number','min="0" max="30"')}</div><div class="row-actions"><button class="btn sm danger" data-action="delete-character">Delete hero</button></div>`;}
function inspectCards(w){const deck=w.decks[state.deck]||[],c=deck.find(x=>x.id===state.chosenCard)||deck[0];return `<h3>Customize Every Card</h3><div class="tabs" style="padding:0">${Object.keys(deckNames).map(k=>`<button data-action="deck-tab" data-id="${k}" class="${state.deck===k?'active':''}">${deckNames[k]} (${w.decks[k]?.length||0})</button>`).join('')}</div><div class="row-actions"><span class="small muted">${deck.length} cards in this deck</span><button class="btn sm positive" data-action="add-card">＋ Card</button></div><div class="inspector-list">${deck.map(x=>`<button class="list-row ${c?.id===x.id?'active':''}" data-action="select-card" data-id="${h(x.id)}"><span class="row-icon">${h(x.icon||'✦')}</span><span class="grow">${h(x.name)}<small>${h(x.type||'Equipment')}</small></span></button>`).join('')}</div>${!c?'<p>No cards in this deck yet.</p>':`<div class="divider"></div>${field('Card name','card.name',c.name)}${field('Symbol','card.icon',c.icon||'✦')}${area('Description','card.description',c.description||'')}${c.image?`<img class="thumbnail" src="${img(c.image)}" alt="Card art"/>`:''}${upload('Upload card artwork','card')}<button class="btn sm ghost" data-action="clear-image" data-target="card">Remove artwork</button><div class="divider"></div>${state.deck==='adventure'?`${dropdown('Card type','card.type',[['enemy','Enemy / combat'],['event','Event'],['treasure','Treasure / discovery']],c.type)}${c.type==='enemy'?`<div class="two-fields">${field('Enemy strength','card.strength',c.strength||0,'number')}${field('Enemy craft (0 = physical)','card.craft',c.craft||0,'number')}</div>`:''}<h3>${c.type==='enemy'?'Reward on victory':'Effects when revealed'}</h3>${effectEditor(c.effects||[],'card')}`:state.deck==='item'?`<h3>Equipment Bonuses</h3><div class="two-fields">${field('Strength bonus','card.bonusStrength',c.bonusStrength||0,'number')}${field('Craft bonus','card.bonusCraft',c.bonusCraft||0,'number')}</div><div class="quick-tip">Equipment is permanent and its bonuses automatically count during combat.</div>`:`<h3>Cast Effect</h3>${dropdown('Spell behavior','card.type',spellTypes,c.type)}${field('Power / amount','card.amount',c.amount||1,'number')}${c.type==='teleport'?dropdown('Destination','card.targetId',w.cells.map(x=>[x.id,x.name]),c.targetId||w.rules.startCellId):''}`}<div class="row-actions"><button class="btn sm danger" data-action="delete-card">Delete card</button></div>`}`;}
function inspectRules(w){return `<h3>Adventure Rules</h3>${dropdown('Starting space','rules.startCellId',w.cells.map(c=>[c.id,c.name]),w.rules.startCellId)}${field('Maximum players','rules.maxPlayers',w.rules.maxPlayers||6,'number','min="1" max="8"')}<div class="two-fields">${field('Dice sides','rules.diceSides',w.rules.diceSides||6,'number','min="2" max="12"')}${field('Enemy damage','rules.enemyDamage',w.rules.enemyDamage||1,'number','min="1" max="10"')}</div>${field('Gold lost after defeat (%)','rules.respawnGoldLossPct',w.rules.respawnGoldLossPct??50,'number','min="0" max="100"')}<div class="divider"></div><h3>How Victory Works</h3><p class="small">Place a <strong class="gold">Win the game</strong> action on any space or adventure card. The first player to trigger it wins. You can create several victory conditions throughout your world.</p><div class="divider"></div><h3>Game Mechanics</h3><div class="rule-line">🎲 Roll one six-sided die each turn.</div><div class="rule-line">⇄ Travel exactly that many connected spaces.</div><div class="rule-line">✦ Resolve every effect on the landed space.</div><div class="rule-line">⚔ Fight enemies with a die + strength or craft + items.</div><div class="rule-line">♥ At zero life, respawn at start, losing half your gold.</div><div class="rule-line">✧ Cast custom spells and collect permanent equipment.</div><div class="quick-tip">For advanced world building, export your JSON, edit it in your favorite text editor, and import it again.</div>`;}
function lobby(){const room=state.room,w=room.scenario,selected=me()?.characterId,taken=new Map(room.players.filter(p=>p.characterId).map(p=>[p.characterId,p.name]));const max=room.scenario.rules.maxPlayers||6;return `<main class="page"><div class="page-top"><div><div class="eyebrow">LIVE MULTIPLAYER · THE GATHERING</div><h2>${h(w.title)}</h2><div class="small muted">Choose a character, invite your friends, then begin the adventure.</div></div><div class="page-actions"><button class="btn sm" data-action="copy-invite">⇧ Copy Invite</button>${isHost()?`<button class="btn sm" data-action="edit-room-world">⚒ Customize World</button>`:''}<button class="btn sm ghost" data-action="leave-room">Leave</button></div></div><div class="lobby-layout"><div><section class="panel"><div class="lobby-title"><div><div class="eyebrow no-line">SELECT YOUR HERO</div><h2>Who will answer the call?</h2></div><span class="tag">${room.players.length} / ${max} players</span></div><div class="lobby-intro"><p class="small">Each adventurer has their own skills and starting resources. One hero per player.</p><div class="character-grid">${w.characters.map(c=>{
 const holder=taken.get(c.id),own=selected===c.id;return `<button class="character-choice ${own?'chosen':''} ${holder&&!own?'taken':''}" data-action="pick-hero" data-id="${h(c.id)}" ${holder&&!own?'disabled':''}>
 ${holder?`<span class="char-taken">${own?'SELECTED':h(holder)}</span>`:''}<div class="character-icon" style="color:${color(c.color)};background:${color(c.color)}19">${c.image?`<img alt="" src="${img(c.image)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%"/>`:h(c.icon||'✦')}</div><b>${h(c.name)}</b><small>${h(c.title)}</small><div class="stats-mini"><span>♥ ${Number(c.health)||0}</span><span>⚔ ${Number(c.strength)||0}</span><span>✧ ${Number(c.craft)||0}</span></div></button>`}).join('')}</div></div></section><section class="panel" style="margin-top:18px"><div class="panel-header"><h3>Explore the Realm</h3></div>${board(w,'lobby',room)}${boardFooter(w)}</section></div>
 <aside><div class="invite-box"><div class="eyebrow no-line" style="justify-content:center">YOUR PRIVATE INVITE CODE</div><div class="invite-code">${h(room.code)}</div><div class="invite-note">Share this code or the link with your friends.</div><button class="btn sm" data-action="copy-invite" style="margin-top:14px">⧉ Copy Room Link</button></div><section class="panel"><div class="panel-header"><h3>The Party</h3></div><div class="panel-pad"><div class="player-list">${room.players.map(p=>playerRow(p,w,room)).join('')}</div>${isHost()?`<button class="btn gold-btn block" data-action="start-game" ${w.characters.length<room.players.length?'disabled':''}>⚔ Begin Adventure →</button><p class="small muted" style="margin:10px 0 0">You can start solo to test your world, or wait for friends to join.</p>`:`<div class="info-box small">⏳ Waiting for the host to begin...</div>`}</div></section><section class="panel" style="margin-top:16px"><div class="panel-header"><h3>Party Chat</h3></div>${chat(room)}</section></aside></div>${footer()}</main>`;}
function playerRow(p,w,room){const c=hero(w,p);return `<div class="player-row"><div class="avatar" style="color:${color(c?.color)}">${c?.image?`<img src="${img(c.image)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:8px"/>`:h(c?.icon||'◇')}</div><div class="player-meta"><b>${h(p.name)} ${p.id===room.youId?'<span class="gold">(you)</span>':''}${p.id===room.hostId?' ✦':''}</b><small>${h(c?.name||'Choosing a hero...')}</small></div><div class="online-dot ${p.online?'':'off'}" title="${p.online?'Online':'Offline'}"></div></div>`;}
function chat(room){return `<div class="chat-box" id="chatbox">${room.chat.length?room.chat.map(m=>`<div class="chat-msg"><b>${h(m.name)}:</b> ${h(m.text)}</div>`).join(''):`<div class="muted small">No messages yet. Say hello!</div>`}</div><form class="chat-form" id="chat-form"><input name="message" maxlength="350" autocomplete="off" placeholder="Send a message..." aria-label="Chat message"/><button class="btn sm" type="submit">Send</button></form>`;}
function inventory(room,p,w){const items=p?.items.map(id=>w.decks.item.find(c=>c.id===id)).filter(Boolean)||[];const spells=p?.spells.map(id=>w.decks.spell.find(c=>c.id===id)).filter(Boolean)||[];return `<div class="subhead">Your Items (${items.length})</div><div class="card-hand">${items.map(c=>`<div class="hand-card"><div class="hand-icon">${c.image?`<img width="32" height="40" style="object-fit:cover;border-radius:4px" src="${img(c.image)}" alt="" />`:h(c.icon||'◆')}</div><div class="grow"><b>${h(c.name)}</b><small>⚔ +${h(c.bonusStrength||0)} &nbsp; ✧ +${h(c.bonusCraft||0)}</small></div></div>`).join('')||'<div class="small muted">No items found yet.</div>'}</div><div class="subhead">Your Spells (${spells.length})</div><div class="card-hand">${spells.map(c=>`<div class="hand-card"><div class="hand-icon">${c.image?`<img width="32" height="40" style="object-fit:cover;border-radius:4px" src="${img(c.image)}" alt="" />`:h(c.icon||'✧')}</div><div class="grow"><b>${h(c.name)}</b><small>${h(c.description)}</small></div><button class="btn sm" data-action="cast-spell" data-id="${h(c.id)}" ${!isMyTurn()?'disabled':''}>Cast</button></div>`).join('')||'<div class="small muted">Your spellbook is empty.</div>'}</div>`;}
function encounterCard(room){const game=room.game;const card=room.scenario.decks.adventure.find(c=>c.id===game.encounter?.cardId);if(!card)return '';return `<div class="battle-card"><div class="battle-symbol">${card.image?`<img alt="Enemy" src="${img(card.image)}" style="width:90px;height:90px;border-radius:8px;object-fit:cover"/>`:h(card.icon||'⚔')}</div><div class="eyebrow no-line" style="justify-content:center">ENCOUNTER</div><h3>${h(card.name)}</h3><p>${h(card.description||'')}</p><div class="small gold">${Number(card.craft)>0?'✧ Craft':'⚔ Strength'} ${h(Number(card.craft)>0?card.craft:card.strength)}</div>${isMyTurn()?`<button class="btn gold-btn block" data-action="fight" style="margin-top:15px">⚔ Roll for Combat</button>`:'<div class="small muted" style="margin-top:15px">Waiting for the adventurer to fight...</div>'}</div>`;}
function gameControls(room){const g=room.game,p=me(),w=room.scenario,turn=room.players[g.turnIndex],mine=isMyTurn();if(room.status==='finished'){const winner=room.players.find(p=>p.id===g.winnerId);return `<div class="battle-card"><div class="battle-symbol">♛</div><div class="eyebrow no-line" style="justify-content:center">THE ADVENTURE IS COMPLETE</div><h3>${h(winner?.name||'An adventurer')} has won!</h3><p>The realm will remember this triumph.</p>${isHost()?`<button class="btn gold-btn block" data-action="restart-room">Play Another Round</button>`:''}</div>`;}
 let text='',btn='';if(!mine){text=`Waiting for <strong>${h(turn?.name||'the adventurer')}</strong> to make their move.`;if(isHost()&&turn?.online===false)btn='<button class="btn danger block" data-action="skip-turn">Skip Disconnected Player →</button>';}
 else if(g.phase==='roll'){text='Your path awaits. Roll the die to discover which spaces you can reach.';btn='<button class="btn gold-btn block" data-action="roll">🎲 Roll the Die</button>';}
 else if(g.phase==='move'){text=`You rolled <strong class="gold">${g.die}</strong>. Select a glowing space on the board to travel there. You can use the route links to cross layers.`;btn='<div class="floating-tip">✧ Glowing green spaces are valid destinations.</div>'+(p.fate>0?'<button class="btn sm" data-action="use-fate">☘ Spend 1 Fate to reroll</button>':'');}
 else if(g.phase==='shop'){const cost=g.shop?.cost||2;text=`A merchant offers you a random equipment card for <b class="gold">${cost} gold</b>.`;btn=mine?`<div class="row-actions"><button class="btn gold-btn" data-action="buy-shop" ${p.gold<cost?'disabled':''}>◆ Buy for ${cost} Gold</button><button class="btn" data-action="skip-shop">Leave Shop</button></div>`:'';}
 else if(g.phase==='choice'){const amount=g.choice?.amount||1;text=`A mysterious blessing offers you a choice. Claim <b class="gold">${amount} gold</b>, or restore <b class="gold">${amount} life</b>.`;btn=mine?`<div class="row-actions"><button class="btn gold-btn" data-action="choose-gold">◆ Take Gold</button><button class="btn" data-action="choose-health">♥ Restore Life</button></div>`:'';}
 else if(g.phase==='encounter'){text='An enemy stands in your way! Fight using Strength or Craft plus item bonuses and a die roll.';btn=encounterCard(room);}
 else if(g.phase==='end'){text='Your space has been resolved. Check your rewards and prepare for the next adventurer.';btn='<button class="btn gold-btn block" data-action="end-turn">Finish Turn →</button>';}
 const lc=g.lastCard;if(g.phase!=='encounter'&&lc){btn+=`<div class="info-box" style="margin-top:13px">${lc.image?`<img src="${img(lc.image)}" style="width:100%;height:92px;object-fit:cover;border-radius:5px;margin-bottom:8px" alt="Card illustration"/>`:``}<div class="info-title">${h(lc.icon||'✦')} ${h(lc.name)}</div><p class="small" style="margin:0">${h(lc.description||'')}</p></div>`;}
 if(g.lastBattle){const b=g.lastBattle;btn+=`<div class="info-box" style="margin-top:12px"><div class="info-title">${b.result==='win'?'Victory!':b.result==='tie'?'A draw':'Defeat'}</div><div class="battle-score"><span class="small">Hero<br/><strong>${b.playerTotal}</strong></span><span>⚔</span><span class="small">Enemy<br/><strong>${b.enemyTotal}</strong></span></div><div class="tiny muted">Dice: you rolled ${b.playerDie}, enemy rolled ${b.enemyDie}</div></div>`;}
 return `<div class="turn-banner"><div><small>ROUND ${g.round} · ${h(g.phase.toUpperCase())}</small><br/><b>${mine?'It’s your turn!':`${h(turn.name)}’s turn`}</b></div><div class="turn-dice">${g.die??'⚄'}</div></div><div class="turn-controls"><p>${text}</p>${btn}</div>`;}
function playing(){const room=state.room,w=room.scenario,p=me(),g=room.game,turn=room.players[g?.turnIndex||0],c=p?hero(w,p):null;return `<main class="page"><div class="page-top"><div><div class="eyebrow">THE ADVENTURE · ROUND ${g?.round||1}</div><h2>${h(w.title)}</h2><div class="small muted">${h(w.tagline||'Journey onward, adventurer.')}</div></div><div class="page-actions"><button class="btn sm" data-action="copy-invite">⧉ Invite Friends</button>${isHost()?`<button class="btn sm ghost" data-action="restart-room">↶ Return to Lobby</button>`:''}<button class="btn sm ghost" data-action="leave-room">Leave</button></div></div><div class="game-layout"><aside class="sidebar-left"><section class="panel"><div class="panel-header"><div class="eyebrow no-line">YOUR ADVENTURER</div><h3>${h(c?.name||'Spectator')}</h3></div><div class="panel-pad" style="text-align:center"><div style="font:59px Georgia;color:${color(c?.color)};height:75px">${c?.image?`<img src="${img(c.image)}" alt="" style="height:72px;width:72px;border-radius:50%;object-fit:cover"/>`:h(c?.icon||'◇')}</div><div class="small muted">${h(c?.title||'Watching the quest')}</div>${p?.characterId?`<div class="player-stats">${[['♥','Life',p.health],['⚔','Strength',p.strength],['✧','Craft',p.craft],['☘','Fate',p.fate],['◆','Gold',p.gold],['◈','Items',p.items.length]].map(([icon,label,val])=>`<div class="stat"><div class="stat-value">${icon} ${h(val)}</div><div class="stat-key">${label}</div></div>`).join('')}</div>`:''}</div></section><section class="panel" style="margin-top:15px"><div class="panel-header"><h3>The Party</h3></div><div class="panel-pad"><div class="player-list">${room.players.map(x=>`<div style="${x.id===turn?.id?'outline:1px solid #c69d5d;border-radius:9px':''}">${playerRow(x,w,room)}</div>`).join('')}</div></div></section></aside>
 <section class="panel board-panel"><div class="board-toolbar"><div><div class="eyebrow no-line">THE GAME BOARD</div><div class="tiny muted">${isMyTurn()&&g.phase==='move'?'Choose one of the glowing destinations.':'Scroll the board to explore. Tap a space to inspect it.'}</div></div>${zoomTools()}</div>${board(w,'game',room)}${boardFooter(w)}</section>
 <aside class="sidebar-right"><div><section class="panel">${gameControls(room)}</section><section class="panel" style="margin-top:15px"><div class="panel-header"><h3>Adventure Journal</h3></div><div class="log-box" id="logbox">${room.log.slice(-35).map(l=>`<div class="log-entry">${h(l.text)}</div>`).join('')}</div></section></div><div><section class="panel"><div class="panel-header"><h3>Equipment & Magic</h3></div><div class="panel-pad">${inventory(room,p,w)}</div></section><section class="panel" style="margin-top:15px"><div class="panel-header"><h3>Party Chat</h3></div>${chat(room)}</section></div></aside></div>${footer()}</main>`;}
function help(){return `<main class="page"><div class="page-top"><div><div class="eyebrow">THE HANDBOOK</div><h2>Everything you need to forge an adventure.</h2></div><button class="btn gold-btn" data-action="new-world">✦ Open World Builder</button></div><div class="help-layout">
 <section class="panel"><div class="panel-header"><h3>01 · Build the World</h3></div><div class="panel-pad"><p>Start with the ready-made <b class="gold">Shattered Realms</b> adventure, or create a completely new world. Change the title, atmosphere, image, colors, and size of your board.</p><p>Design circular <b class="gold">layers</b> that create paths through your adventure. Add or remove spaces, drag them anywhere, and link two spaces to create gates, bridges, secret routes, or alternate paths.</p><p>Select any space to write its own story and define a sequence of actions — draw encounters, grant resources, teleport a character, or trigger victory.</p></div></section>
 <section class="panel"><div class="panel-header"><h3>02 · Invent the Adventure</h3></div><div class="panel-pad"><p>Create as many adventurers and cards as your world needs. Give every character a portrait, name, special identity, starting Life, Strength, Craft, Fate and Gold.</p><p>Adventure cards can be <b class="gold">enemies, events or treasures</b>. Build custom equipment with Strength and Craft bonuses, and custom spells for healing, movement, gold, magic or escape.</p><p>Add your own background art, space images, character portraits and card illustrations. They travel inside the world file when exported.</p></div></section>
 <section class="panel"><div class="panel-header"><h3>03 · Play Online</h3></div><div class="panel-pad"><p>Press <b class="gold">Host Game</b> to create a multiplayer room. Copy the room invitation URL or six-character code and share it. Friends join from their own phones or computers, no registration required.</p><p>Choose different heroes in the lobby, then the host begins. Take turns rolling one die, moving exactly that many spaces over connected paths, and resolving the destination's actions. Everyone sees movement, combat results and the shared journal immediately.</p><p>If someone refreshes their browser, the game remembers their player session on that device.</p></div></section>
 <section class="panel"><div class="panel-header"><h3>04 · Win, Save & Share</h3></div><div class="panel-pad"><p>Combat uses <b class="gold">Strength or Craft + an ordinary six-sided die</b>, along with equipped item bonuses. Winning can award items, gold, or other custom effects. Losing a fight costs one Life.</p><p>When Life reaches zero, the adventurer returns to the starting space and loses half their gold. The first player to trigger a <b class="gold">Victory</b> action wins.</p><p>Worlds save in this browser. Use Export to create a portable JSON file and Import to bring a world into another browser. Rooms are also saved to the server while hosted.</p><div class="quick-tip">This is an original fantasy adventure toolkit inspired by classic exploration board games, not official Talisman software or content.</div></div></section></div>${footer()}</main>`;}
function modal(){const m=state.modal;if(!m)return '';if(m==='import')return `<div class="modal-shade" data-action="modal-backdrop"><div class="modal"><div class="eyebrow">TRANSFER A WORLD</div><h2>Import a world</h2><p>Choose a JSON world file. It will become an editable world in your library.</p><label class="upload-box" style="margin-top:20px">⇧ Select world JSON<input type="file" accept="application/json,.json" id="import-file"/></label><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button></div></div></div>`;
 if(m==='host'||m==='join')return `<div class="modal-shade" data-action="modal-backdrop"><form class="modal" id="entry-form"><div class="eyebrow">${m==='host'?'START YOUR ADVENTURE':'JOIN A FRIEND'}</div><h2>${m==='host'?'Gather your party.':'Your adventure awaits.'}</h2><p>${m==='host'?'Create a private room and invite friends using a link or code.':'Enter the room code and a name your friends will recognize.'}</p><label>Your adventurer name<input name="nickname" maxlength="26" required placeholder="Your name" value="${h(state.name)}" autocomplete="nickname"/></label>${m==='join'?`<label>Invitation code<input name="roomCode" maxlength="6" required class="code-input" value="${h(state.joiningCode)}" placeholder="ABC123"/></label>`:''}<div class="modal-actions"><button class="btn ghost" data-action="close-modal" type="button">Cancel</button><button class="btn gold-btn" type="submit">${m==='host'?'Create Room →':'Join Room →'}</button></div></form></div>`;
 if(m==='space'){const c=sourceForCell(state.room?.scenario||state.draft,state.chosenCell);return `<div class="modal-shade" data-action="modal-backdrop"><div class="modal"><div class="eyebrow">THE REALM</div><h2>${h(c?.icon||'✦')} ${h(c?.name||'Space')}</h2><p>${h(c?.description||'')}</p><div class="small gold">${(c?.actions||[]).map(fx=>effects.find(x=>x[0]===fx.type)?.[1]||fx.type).join(' · ')}</div><div class="modal-actions"><button class="btn gold-btn" data-action="close-modal">Close</button></div></div></div>`;}
 return '';
}
function render(){
 const el=$('#app');if(!el)return;
 const sameView=state.renderedView===state.view;
 const previousScroll=sameView?$('.board-scroll'):null,position=previousScroll?{left:previousScroll.scrollLeft,top:previousScroll.scrollTop}:null;
 const oldInspector=sameView?$('.inspector-body'):null,inspectorY=oldInspector?.scrollTop||0;
 const chatInput=$('.chat-form input'),chatText=chatInput?.value||'',chatFocused=document.activeElement===chatInput;
 let content=state.view==='home'?home():state.view==='editor'?editor():state.view==='lobby'&&state.room?lobby():state.view==='game'&&state.room?playing():state.view==='help'?help():home();
 el.innerHTML=topbar()+content+modal();state.renderedView=state.view;
 const boardNow=$('.board-scroll');if(boardNow&&position){boardNow.scrollLeft=position.left;boardNow.scrollTop=position.top;}
 const inspectNow=$('.inspector-body');if(inspectNow)inspectNow.scrollTop=inspectorY;
 const newChat=$('.chat-form input');if(newChat&&chatText){newChat.value=chatText;if(chatFocused)newChat.focus();}
 const logbox=$('#logbox'),chatbox=$('#chatbox');if(logbox)logbox.scrollTop=logbox.scrollHeight;if(chatbox)chatbox.scrollTop=chatbox.scrollHeight;
 document.title=`${state.view==='editor'?state.draft?.title+' — ':''}Arcana Forge`;
}
function draftFrom(w,fromRoom=false){state.draft=clone(w);state.fromRoom=fromRoom;state.chosenCell=w.cells[0]?.id||null;state.chosenLayer=w.layers[0]?.id||null;state.chosenCharacter=w.characters[0]?.id||null;state.deck='adventure';state.chosenCard=w.decks.adventure?.[0]?.id||null;state.tab='board';state.editorTool='select';state.linkSource=null;state.view='editor';state.zoom=1;render();window.scrollTo(0,0);}
function saveDraft(){if(!state.draft)return;const w=clone(state.draft);let ix=worlds.findIndex(x=>x.id===w.id);if(ix<0)worlds.push(w);else worlds[ix]=w;state.selection=w.id;if(persist())toast('World saved to your library.');}
function download(w){const blob=new Blob([JSON.stringify(w,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(w.title||'world').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'.arcana.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function emit(event,payload={},onSuccess){if(!socket.connected){toast('Disconnected. Check your internet connection and try again.',true);return;}socket.timeout(7500).emit(event,payload,(err,res)=>{if(err||!res?.ok){toast(res?.error||'The server did not respond. Please try again.',true);return;}if(onSuccess)onSuccess(res);});}
function roomCred(code){try{return JSON.parse(localStorage.getItem('arcana-room-'+code)||'null')}catch{return null}}
function saveRoomCred(code,token){try{localStorage.setItem('arcana-room-'+code,JSON.stringify({token,name:state.name}));localStorage.setItem('arcana-last-room',code);}catch{}}
function enterRoom(res){saveRoomCred(res.code,res.token);state.modal=null;const url=new URL(location.href);url.searchParams.set('room',res.code);history.replaceState({},'',url);state.joiningCode=res.code;render();}
function leaveRoom(){emit('room:leave',{},()=>{state.room=null;state.view='home';state.fromRoom=false;const url=new URL(location.href);url.searchParams.delete('room');history.replaceState({},'',url);render();});}
function initSocket(){socket.on('connect',()=>{state.connected=true;const queryCode=new URLSearchParams(location.search).get('room');const code=state.room?.code||queryCode;const stored=code&&roomCred(code);if(code&&stored?.token){emit('room:join',{code,token:stored.token,name:stored.name},res=>{enterRoom(res);});}else if(queryCode&&!state.room){state.joiningCode=queryCode;state.modal='join';render();}});
 socket.on('disconnect',()=>{state.connected=false;toast('Connection lost. Reconnecting…',true);});
 socket.on('room:state',room=>{if(!room.scenario&&state.room?.code===room.code)room.scenario=state.room.scenario;if(!room.scenario)return;state.room=room;if(!(state.view==='editor'&&state.fromRoom)){state.view=room.status==='lobby'?'lobby':'game';render();} });}
function chosen(prefix){const w=state.draft;if(!w)return null;if(prefix==='board')return w;if(prefix==='rules')return w.rules;if(prefix==='layer')return w.layers.find(l=>l.id===state.chosenLayer)||w.layers[0];if(prefix==='cell')return sourceForCell(w,state.chosenCell)||w.cells[0];if(prefix==='character')return w.characters.find(c=>c.id===state.chosenCharacter)||w.characters[0];if(prefix==='card')return w.decks[state.deck].find(c=>c.id===state.chosenCard)||w.decks[state.deck][0];return null;}
function setBound(bind,value){const path=bind.split('.'),obj=chosen(path.shift());if(!obj)return;let ref=obj;for(let i=0;i<path.length-1;i++){if(ref[path[i]]==null)ref[path[i]]={};ref=ref[path[i]];}const key=path[path.length-1],numeric=['health','strength','craft','fate','gold','maxPlayers','radius','amount','bonusStrength','bonusCraft','diceSides','enemyDamage','respawnGoldLossPct','boardOpacity'];ref[key]=numeric.includes(key)?Number(value):value;if(bind==='cell.layerId')state.chosenLayer=value;}
function newCell(layer){const w=state.draft;const id=D.uid();const count=w.cells.filter(c=>c.layerId===layer).length+1;w.cells.push({id,layerId:layer,name:`New Space ${count}`,subtitle:'NEW LAND',description:'Write what happens when adventurers come here.',icon:'✦',color:'',image:'',x:null,y:null,actions:[{type:'draw_adventure',amount:1,text:''}],links:[]});state.chosenCell=id;state.tab='cell';render();}
function unlinkCells(a,b){const w=state.draft;for(const c of w.cells)if(c.id===a||c.id===b)c.links=(c.links||[]).filter(id=>id!==(c.id===a?b:a));}
function selectTile(id){if(state.suppressClick){state.suppressClick=false;return;}if(state.view==='editor'){
 const w=state.draft,c=sourceForCell(w,id);if(!c)return;
 if(state.editorTool==='link'){if(!state.linkSource){state.linkSource=id;state.chosenCell=id;state.tab='cell';toast('Now select the second space to connect.');}
 else if(state.linkSource===id){toast('Choose a different space.',true);return;}
 else {const source=sourceForCell(w,state.linkSource);if(source&&!source.links.includes(id))source.links.push(id);state.chosenCell=state.linkSource;state.linkSource=null;state.editorTool='select';toast('Spaces connected — the route works in both directions.');}}
 else {state.chosenCell=id;state.chosenLayer=c.layerId;state.tab='cell';}render();return;
 }
 if(state.view==='game'&&state.room){const g=state.room.game;if(isMyTurn()&&g.phase==='move'&&g.moves.includes(id)){emit('turn:move',{cellId:id});return;}state.chosenCell=id;state.modal='space';render();}
}
function createCard(){const key=state.deck,w=state.draft,c={id:D.uid(),name:key==='adventure'?'New Encounter':key==='item'?'New Equipment':'New Spell',description:'Write your card description.',icon:key==='adventure'?'⚔':key==='item'?'◆':'✧',image:''};if(key==='adventure')Object.assign(c,{type:'event',strength:3,craft:0,effects:[{type:'gold',amount:1,text:''}]});if(key==='item')Object.assign(c,{bonusStrength:1,bonusCraft:0});if(key==='spell')Object.assign(c,{type:'heal',amount:1});w.decks[key].push(c);state.chosenCard=c.id;render();}
async function photoToData(file){if(file.size>16*1024*1024)throw Error('Please use an image smaller than 16 MB.');return await new Promise((resolve,reject)=>{
 const reader=new FileReader();reader.onerror=()=>reject(new Error('Unable to read the image.'));reader.onload=()=>{const preview=new Image();preview.onerror=()=>reject(new Error('Unsupported image.'));preview.onload=()=>{const scale=Math.min(1,900/Math.max(preview.width,preview.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(preview.width*scale));canvas.height=Math.max(1,Math.round(preview.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(preview,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.77));};preview.src=reader.result;};reader.readAsDataURL(file);
 });}
async function fileChange(target){if(target.id==='import-file'){const file=target.files?.[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(!obj||!Array.isArray(obj.layers)||!Array.isArray(obj.cells)||!Array.isArray(obj.characters)||!obj.decks||!obj.rules)throw Error('Not an Arcana Forge world file.');if(obj.cells.length>160||obj.layers.length>12)throw Error('Too many board spaces or layers.');obj.id=D.uid();worlds.push(obj);state.selection=obj.id;if(!persist())return;state.modal=null;draftFrom(obj);toast('World imported. Save any changes when finished.');}catch(err){toast(err.message,true);}return;}
 const kind=target.dataset.upload;if(!kind)return;const file=target.files?.[0];if(!file)return;
 try{const data=await photoToData(file);const obj=kind==='board'?state.draft.theme:chosen(kind);if(!obj)throw Error('Nothing selected to receive the image.');if(kind==='board')obj.boardImage=data;else obj.image=data;toast('Artwork added.');render();}catch(err){toast(err.message,true);}
}
function handleClick(evt){const target=evt.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id,w=state.draft;evt.preventDefault();
 switch(action){
 case 'home':state.modal=null;state.view='home';render();window.scrollTo(0,0);break;
 case 'help':state.view='help';state.modal=null;render();break;
 case 'view-room':if(state.room){state.view=state.room.status==='lobby'?'lobby':'game';state.modal=null;render();}break;
 case 'new-world':draftFrom(D.makeBlank());break;
 case 'edit-world':state.selection=id;draftFrom(worlds.find(x=>x.id===id));break;
 case 'duplicate-world':{const copy=clone(worlds.find(x=>x.id===id));copy.id=D.uid();copy.title+=' (copy)';worlds.push(copy);state.selection=copy.id;persist();render();toast('World duplicated.');break;}
 case 'delete-world':if(confirm('Delete this world from this browser? Export a copy first if you want to keep it.')){worlds=worlds.filter(x=>x.id!==id);if(!worlds.length)worlds=[D.makeDefault()];state.selection=worlds[0].id;persist();render();}break;
 case 'export-world':{const world=worlds.find(x=>x.id===id);if(world)download(world);break;}
 case 'export-draft':download(w);break;
 case 'save-world':saveDraft();render();break;
 case 'close-editor':state.view=state.fromRoom?'lobby':'home';state.fromRoom=false;render();break;
 case 'host-world':state.pendingWorldId=id;state.modal='host';render();break;
 case 'host-draft':saveDraft();state.pendingWorldId=w.id;state.modal='host';render();break;
 case 'open-join':state.joiningCode='';state.modal='join';render();break;
 case 'join-code':state.joiningCode=($('#home-code')?.value||'').trim().toUpperCase();state.modal='join';render();break;
 case 'close-modal':state.modal=null;render();break;
 case 'modal-backdrop':if(evt.target===target){state.modal=null;render();}break;
 case 'import-open':state.modal='import';render();break;
 case 'zoom-in':state.zoom=Math.min(2.25,state.zoom+.25);render();break;
 case 'zoom-out':state.zoom=Math.max(.75,state.zoom-.25);render();break;
 case 'zoom-reset':state.zoom=1;render();break;
 case 'editor-tab':state.tab=id;state.editorTool='select';state.linkSource=null;render();break;
 case 'select-layer':state.chosenLayer=id;render();break;
 case 'add-layer':{if(w.layers.length>=12){toast('Maximum of 12 layers.',true);break;}const layer={id:D.uid(),name:`New Realm ${w.layers.length+1}`,radius:Math.max(10,44-w.layers.length*9),color:'#81baa5'};w.layers.push(layer);state.chosenLayer=layer.id;state.tab='layer';render();break;}
 case 'delete-layer':{if(w.layers.length<=1){toast('Keep at least one layer.',true);break;}const l=chosen('layer');const doomed=w.cells.filter(c=>c.layerId===l.id);if(!confirm(`Delete ${l.name} and its ${doomed.length} spaces?`))break;const doomedSet=new Set(doomed.map(c=>c.id));w.layers=w.layers.filter(x=>x.id!==l.id);w.cells=w.cells.filter(c=>!doomedSet.has(c.id));w.cells.forEach(c=>c.links=(c.links||[]).filter(id=>!doomedSet.has(id)));if(w.cells.length<2)for(let i=0;i<2;i++)newCell(w.layers[0].id);w.rules.startCellId=w.cells.some(c=>c.id===w.rules.startCellId)?w.rules.startCellId:w.cells[0].id;state.chosenLayer=w.layers[0].id;state.chosenCell=w.cells[0].id;state.tab='layer';render();break;}
 case 'reset-layer-layout':{const layer=chosen('layer');w.cells.filter(c=>c.layerId===layer.id).forEach(c=>{c.x=null;c.y=null;});render();toast('Layer positions reset to the ring.');break;}
 case 'add-cell':newCell(target.dataset.layer||state.chosenLayer||w.layers[0].id);break;
 case 'delete-cell':{if(w.cells.length<=2){toast('Keep at least two spaces.',true);break;}const c=chosen('cell');if(!confirm(`Delete ${c.name}?`))break;w.cells=w.cells.filter(x=>x.id!==c.id);w.cells.forEach(x=>x.links=(x.links||[]).filter(y=>y!==c.id));state.chosenCell=w.cells[0].id;if(w.rules.startCellId===c.id)w.rules.startCellId=w.cells[0].id;render();break;}
 case 'reset-cell-position':{const c=chosen('cell');c.x=null;c.y=null;render();break;}
 case 'link-mode':state.editorTool=state.editorTool==='link'?'select':'link';state.linkSource=null;render();break;
 case 'unlink':unlinkCells(state.chosenCell,id);render();break;
 case 'tile':selectTile(id);break;
 case 'add-effect':{const obj=chosen(target.dataset.prefix),key=target.dataset.prefix==='card'?'effects':'actions';if(!obj[key])obj[key]=[];obj[key].push({type:'gold',amount:1,text:''});render();break;}
 case 'remove-effect':{const obj=chosen(target.dataset.prefix),key=target.dataset.prefix==='card'?'effects':'actions';obj[key]?.splice(Number(target.dataset.index),1);render();break;}
 case 'select-character':state.chosenCharacter=id;render();break;
 case 'add-character':{const c={id:D.uid(),name:'New Adventurer',title:'The Explorer',icon:'✦',color:'#8ab9ac',health:5,strength:3,craft:3,fate:3,gold:1,image:''};w.characters.push(c);state.chosenCharacter=c.id;render();break;}
 case 'delete-character':{if(w.characters.length<=1){toast('Keep at least one hero.',true);break;}if(!confirm('Delete this hero?'))break;const c=chosen('character');w.characters=w.characters.filter(x=>x.id!==c.id);state.chosenCharacter=w.characters[0].id;render();break;}
 case 'deck-tab':state.deck=id;state.chosenCard=w.decks[id]?.[0]?.id||null;render();break;
 case 'select-card':state.chosenCard=id;render();break;
 case 'add-card':if(w.decks[state.deck].length>=150)toast('Maximum 150 cards per deck.',true);else createCard();break;
 case 'delete-card':{const c=chosen('card');if(!confirm(`Delete ${c.name}?`))break;w.decks[state.deck]=w.decks[state.deck].filter(x=>x.id!==c.id);state.chosenCard=w.decks[state.deck][0]?.id||null;render();break;}
 case 'clear-image':{const kind=target.dataset.target,obj=kind==='board'?w.theme:chosen(kind);if(obj){if(kind==='board')obj.boardImage='';else obj.image='';}render();break;}
 case 'edit-room-world':draftFrom(state.room.scenario,true);break;
 case 'apply-room-world':emit('room:updateScenario',{scenario:w},()=>{state.view='lobby';state.fromRoom=false;toast('The updated world is now shared with the room.');render();});break;
 case 'pick-hero':emit('room:character',{characterId:id});break;
 case 'start-game':emit('room:start');break;
 case 'roll':emit('turn:roll');break;
 case 'fight':emit('turn:fight');break;
 case 'use-fate':emit('turn:fate');break;
 case 'buy-shop':emit('turn:shop',{buy:true});break;
 case 'skip-shop':emit('turn:shop',{buy:false});break;
 case 'choose-gold':emit('turn:choice',{type:'gold'});break;
 case 'choose-health':emit('turn:choice',{type:'health'});break;
 case 'end-turn':emit('turn:end');break;
 case 'skip-turn':emit('turn:skip');break;
 case 'cast-spell':emit('turn:spell',{cardId:id});break;
 case 'restart-room':if(confirm('Return all players to the lobby? This resets the current run.'))emit('room:restart');break;
 case 'leave-room':if(confirm('Leave the room? You can rejoin later using the same code and browser.'))leaveRoom();break;
 case 'copy-invite':{const link=new URL(location.href);link.searchParams.set('room',state.room.code);const url=link.toString();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>toast('Invite link copied!')).catch(()=>prompt('Copy this invite link:',url));else prompt('Copy this invite link:',url);break;}
 default:break;
 }
}
function onChange(evt){const t=evt.target;
 if(t.dataset.bind){setBound(t.dataset.bind,t.value);render();return;}
 if(t.dataset.actionSelect==='select-cell'){state.chosenCell=t.value;const c=sourceForCell(state.draft,t.value);state.chosenLayer=c?.layerId;render();}
}
async function handleSubmit(evt){if(evt.target.id==='entry-form'){
 evt.preventDefault();const fd=new FormData(evt.target),name=String(fd.get('nickname')||'').trim(),code=String(fd.get('roomCode')||'').trim().toUpperCase();if(!name){toast('Please enter a name.',true);return;}state.name=name;localStorage.setItem('arcana-nickname',name);
 if(state.modal==='host'){const scenario=worlds.find(w=>w.id===state.pendingWorldId)||state.draft||currentWorld();emit('room:create',{scenario,name},enterRoom);}
 else emit('room:join',{code,name,token:roomCred(code)?.token},enterRoom);
 }
 if(evt.target.id==='chat-form'){evt.preventDefault();const input=evt.target.elements.message,text=input.value.trim();if(text)emit('room:chat',{text});input.value='';}
}
function enableDragging(){let drag=null;
 document.addEventListener('pointerdown',evt=>{
 if(state.view!=='editor'||state.editorTool!=='select')return;const tile=evt.target.closest('.tile.editable');if(!tile)return;const rect=tile.closest('.board-scene').getBoundingClientRect();drag={id:tile.dataset.id,rect,x:evt.clientX,y:evt.clientY,tile,moved:false};
 });
 document.addEventListener('pointermove',evt=>{
 if(!drag)return;const dx=evt.clientX-drag.x,dy=evt.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<7)return;drag.moved=true;
 if(evt.cancelable)evt.preventDefault();const x=Math.max(3,Math.min(97,(evt.clientX-drag.rect.left)/drag.rect.width*100)),y=Math.max(3,Math.min(97,(evt.clientY-drag.rect.top)/drag.rect.height*100));drag.tile.style.left=x+'%';drag.tile.style.top=y+'%';const c=sourceForCell(state.draft,drag.id);if(c){c.x=Number(x.toFixed(2));c.y=Number(y.toFixed(2));}
 });
 document.addEventListener('pointerup',()=>{if(!drag)return;const moved=drag.moved,id=drag.id;drag=null;if(moved){state.suppressClick=true;state.chosenCell=id;state.chosenLayer=sourceForCell(state.draft,id)?.layerId;state.tab='cell';render();setTimeout(()=>state.suppressClick=false,20);}});
 document.addEventListener('pointercancel',()=>{drag=null;});
}
document.addEventListener('click',handleClick);
document.addEventListener('change',evt=>{if(evt.target.matches('input[type="file"]'))fileChange(evt.target);else onChange(evt);});
document.addEventListener('submit',handleSubmit);
window.addEventListener('keydown',evt=>{if(evt.key==='Escape'&&state.modal){state.modal=null;render();}});
enableDragging();initSocket();render();
})();
